src/server.js:
```js
const http = require('node:http');
const { sendJson, sendNotFound } = require('./http');
const DEFAULT_PORT = 3000;

function resolvePort(env = process.env) {
  const raw = env.PORT;
  if (raw === undefined || raw === '') return DEFAULT_PORT;
  const port = Number(raw);
  if (!Number.isInteger(port) || port < 0 || port > 65535) {
    throw new RangeError(`Invalid PORT: ${raw}`);
  }
  return port;
}

function handleRequest(req, res) {
  const url = new URL(req.url, 'http://localhost');
  if (req.method === 'GET' && url.pathname === '/health') return sendJson(res,200,{status:'ok'});
  return sendNotFound(res);
}

function createServer() { return http.createServer(handleRequest); }

function startServer({ env = process.env, log = console.log } = {}) {
  const port = resolvePort(env);
  const server = createServer();
  server.on('error', (err) => { console.error(`Failed to start server: ${err.message}`); process.exitCode = 1; ...});
  server.listen(port, () => log(`Server listening on port ${port}`));
  return server;
}

if (require.main === module) {
  startServer();
}
module.exports = { DEFAULT_PORT, resolvePort, handleRequest, createServer, startServer };
```

Careful: on listen error, server.listen callback won't run, 'error' emitted. Must exit non-zero. Use process.exit(1) after console.error. But for a library, hard exit is undesirable; use `server.on('error', err => { console.error(err); process.exitCode=1; })` — but server error event with no listener would crash with stack (also non-zero, stderr non-empty). For clean: in startServer, attach error handler that logs and process.exit(1). Acceptable since startServer is startup entry. But if test imports createServer only, fine.

