{
  "name": "greenfield-members",
  "version": "0.1.0",
  "description": "会员管理系统 · C0 工程骨架",
  "private": true,
  "type": "commonjs",
  "engines": {
    "node": ">=20"
  },
  "scripts": {
    "start": "node src/server.js",
    "test": "node --test test/"
  },
  "dependencies": {},
  "devDependencies": {}
}

'use strict';

const { test, before, after } = require('node:test');
const assert = require('node:assert');
const http = require('node:http');
const path = require('node:path');
const { spawn } = require('node:child_process');

const {
  DEFAULT_PORT,
  resolvePort,
  createServer,
} = require('../src/server');

const SERVER_PATH = path.join(__dirname, '..', 'src', 'server.js');

function request(port, pathname) {
  return new Promise((resolve, reject) => {
    const req = http.get(
      { host: '127.0.0.1', port, path: pathname, agent: false },
      (res) => {
        const chunks = [];
        res.on('data', (chunk) => chunks.push(chunk));
        res.on('end', () => {
          resolve({
            statusCode: res.statusCode,
            headers: res.headers,
            body: Buffer.concat(chunks).toString('utf8'),
          });
        });
      }
    );
    req.on('error', reject);
    req.setTimeout(5000, () => req.destroy(new Error('request timeout')));
  });
}

function listen(server) {
  return new Promise((resolve, reject) => {
    server.once('error', reject);
    server.listen(0, '127.0.0.1', () => {
      server.removeListener('error', reject);
      resolve(server.address().port);
    });
  });
}

function close(server) {
  return new Promise((resolve, reject) => {
    server.close((err) => (err ? reject(err) : resolve()));
  });
}

async function waitForHealth(port, timeoutMs = 5000) {
  const deadline = Date.now() + timeoutMs;
  let lastError;
  while (Date.now() < deadline) {
    try {
      return await request(port, '/health');
    } catch (err) {
      lastError = err;
      await new Promise((r) => setTimeout(r, 50));
    }
  }
  throw lastError || new Error('server did not become ready');
}

const SECURITY_HEADERS = {
  'x-content-type-options': 'nosniff',
  'x-frame-options': 'DENY',
  'referrer-policy': 'no-referrer',
};

test('resolvePort 在未设置 PORT 时使用默认端口 3000', () => {
  assert.strictEqual(DEFAULT_PORT, 3000);
  assert.strictEqual(resolvePort({}), 3000);
});

test('resolvePort 在设置 PORT 时优先使用 PORT', () => {
  assert.strictEqual(resolvePort({ PORT: '4123' }), 4123);
});

test('GET /health 返回 200、固定 JSON 与安全响应头', async () => {
  const server = createServer();
  const port = await listen(server);
  try {
    const res = await request(port, '/health');
    assert.strictEqual(res.statusCode, 200);
    assert.strictEqual(res.headers['content-type'], 'application/json; charset=utf-8');
    assert.strictEqual(res.body, '{"status":"ok"}');
    for (const [name, expected] of Object.entries(SECURITY_HEADERS)) {
      assert.strictEqual(res.headers[name], expected);
    }
  } finally {
    await close(server);
  }
});

test('GET /missing 返回 404、固定 JSON 与安全响应头', async () => {
  const server = createServer();
  const port = await listen(server);
  try {
    const res = await request(port, '/missing');
    assert.strictEqual(res.statusCode, 404);
    assert.strictEqual(res.headers['content-type'], 'application/json; charset=utf-8');
    assert.strictEqual(res.body, '{"error":"not_found"}');
    for (const [name, expected] of Object.entries(SECURITY_HEADERS)) {
      assert.strictEqual(res.headers[name], expected);
    }
  } finally {
    await close(server);
  }
});

test('PORT 覆盖默认端口：子进程按 PORT 监听并可访问 /health', async () => {
  // 先占位取得一个空闲端口，避免与固定端口冲突；再通过 PORT 环境变量覆盖默认端口。
  const probe = createServer();
  const port = await listen(probe);
  await close(probe);

  const child = spawn(process.execPath, [SERVER_PATH], {
    env: { ...process.env, PORT: String(port) },
    stdio: ['ignore', 'pipe', 'pipe'],
  });
  let stderr = '';
  child.stderr.on('data', (chunk) => {
    stderr += chunk.toString('utf8');
  });

  try {
    const res = await waitForHealth(port);
    assert.strictEqual(res.statusCode, 200);
    assert.strictEqual(res.body, '{"status":"ok"}');
  } finally {
    child.kill('SIGTERM');
    await new Promise((resolve) => child.once('exit', resolve));
  }

  assert.strictEqual(stderr, '', `子进程不应输出错误：${stderr}`);
});
